const input=$json.body??$json;
const dispatch=input.dispatch??{};
const receipt=input.delivery_receipt??input.receipt??{};
const response=input.seller_response??input.response??{};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const dispatchId=String(input.dispatch_id||dispatch.dispatch_id||"").trim();
const deliveryStatus=String(receipt.status||input.delivery_status||"").toLowerCase();
const responseReceived=Boolean(input.response_received||response.received===true||String(response.status||"").toLowerCase()==="received"||String(response.text||"").trim());
const responseText=String(response.text||input.response_text||"").trim();
const timeout=Boolean(input.response_timeout||input.timed_out||String(input.response_state||"").toLowerCase()==="timeout");
const deliveryFailed=["failed","undelivered","rejected","bounced"].includes(deliveryStatus);
const delivered=["delivered","sent","accepted"].includes(deliveryStatus);
const pending=["pending","queued","processing",""].includes(deliveryStatus);
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id&&dispatchId);
let status="receipt_pending",nextWorkflow="WF-290",humanReview=false,reason="awaiting provider delivery receipt";
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";humanReview=true;reason="missing deal/lead/property/dispatch identity";}
else if(blockers.length){status="response_routing_blocked";nextWorkflow="WF-126";humanReview=true;reason="active blockers present";}
else if(deliveryFailed){status="delivery_failed";nextWorkflow="WF-289";humanReview=true;reason="provider delivery failed; retry requires controlled dispatch";}
else if(responseReceived){status="seller_response_received";nextWorkflow="WF-291";humanReview=false;reason="seller response received and ready for classification";}
else if(timeout){status="seller_response_timeout";nextWorkflow="WF-292";humanReview=false;reason="seller response window expired";}
else if(delivered){status="delivered_awaiting_response";nextWorkflow="WF-290";humanReview=false;reason="offer delivered; awaiting seller response";}
else if(pending){status="receipt_pending";nextWorkflow="WF-290";humanReview=false;reason="provider receipt still pending";}
const routing={dispatch_id:dispatchId,delivery_status:deliveryStatus||"unknown",delivered,response_received:responseReceived,response_text_present:Boolean(responseText),response_timeout:timeout,delivery_failed:deliveryFailed,next_action:nextWorkflow};
return [{json:{...input,workflow:"WF-290",workflow_name:"Offer Delivery Receipt → Seller Response / Timeout Controller",status,delivery_response_routing:routing,next_workflow:nextWorkflow,human_review_required:humanReview,routing_reason:reason,audit:{event_type:"offer_delivery_receipt_seller_response_timeout",idempotency_key:input.idempotency_key||`wf-290:${dispatchId||"unknown"}:${input.version||1}`}}}];
